def main() -> None:
    out = Path(__file__).resolve().parent
    for step, rows in A.items():
        answers = []
        for i, r in enumerate(rows, 1):
            code, text = r[0], r[1]
            note = r[2] if len(r) > 2 else None
            review = text.rstrip().endswith("?")
            text = text.rstrip().removesuffix("?").rstrip()
            kind, label = KIND[code]
            answers.append({"id": f"a{i:02d}", "text": text, "label": label, "kind": kind,
                            "owner_review": review, **({"note": note} if note else {})})
        (out / f"{step}.yaml").write_text(
            f"# Generated from _answers.py. Edit there.\nstep: {step}\n" + yaml.safe_dump({"answers": answers}, sort_keys=False, allow_unicode=True, width=110),
            encoding="utf-8")
        print(step, len(answers), "owner_review", sum(a["owner_review"] for a in answers))


if __name__ == "__main__":
    main()
